-- Notas de parche 0.1.0 → 0.5.0: todo lo publicado hasta hoy, escrito para los jugadores a partir del historial de
-- git (cada versión lleva la fecha de su último commit, en UTC). Se insertan ya publicadas. Si una versión ya existe
-- (por ejemplo, escrita a mano desde Administración), se respeta la que hay. "highlight" solo aparece cuando es true,
-- como lo guarda ChangelogChange.
INSERT INTO public."Changelog" (id, version, title, summary, date, published, content, "createdAt", "updatedAt")
VALUES
    (gen_random_uuid()::text, '0.1.0', 'Primeros minijuegos',
     'Nace Pokémon Universe: salas privadas con amigos, 28 minijuegos, sesiones de varias partidas y perfil con estadísticas.',
     TIMESTAMP '2026-08-30 18:10:37', true,
     $json$[
       {"type": "NEW", "text": "Crea una sala privada, comparte su código de seis caracteres y jugad juntos. Puedes entrar con tu cuenta o como invitado, sin registrarte.", "highlight": true},
       {"type": "MINIGAMES", "text": "Llegan 28 minijuegos para jugar con o contra tus amigos, cada uno con sus propios ajustes en el lobby.", "highlight": true},
       {"type": "MINIGAMES", "text": "Para adivinar: ¿Quién es ese Pokémon?, Zoomed Pokémon, Adivina el Grito, Adivina por la Paleta, Pokédex Entry Guess, Guess from Stats, Learnset Guess y Shiny Quiz."},
       {"type": "MINIGAMES", "text": "Carreras y retos: Pokédex Distance, Pokédle Race, Type Duel, Type Chain, Pokémon Bingo, Pokémon Connections, Pokémon Trivia, Higher or Lower y Higher or Lower: Cartas, que compara el precio de cartas del TCG."},
       {"type": "MINIGAMES", "text": "Para engañar y colaborar: Pokémon Impostor, One of Us Is Fake, PokéTaboo, Sketchmon (dibuja en tiempo real) y Quién es Quién — Pokémon, por equipos y con el cursor del compañero a la vista."},
       {"type": "MINIGAMES", "text": "Subastas y votaciones: Pokémon Team Auction, Pokémon Bluff Auction, Secret Ranking, Most Likely To, Would You Rather Pokémon y Pokémon Red Flag / Green Flag."},
       {"type": "NEW", "text": "Sesiones de varias partidas: repite el mismo minijuego, deja que la sala lo sortee o votad el siguiente al acabar cada partida.", "highlight": true},
       {"type": "NEW", "text": "Al final de la sesión verás al campeón y una gráfica con la evolución de los puntos de cada jugador."},
       {"type": "NEW", "text": "Perfil con foto propia o avatar predefinido y estadísticas de cada minijuego. Los invitados también pueden subir su foto."},
       {"type": "NEW", "text": "Las cuentas registradas guardan sus ajustes de cada minijuego y sus propias preguntas."},
       {"type": "NEW", "text": "Crea categorías propias para One of Us Is Fake y dilemas propios para Would You Rather Pokémon, que también puedes importar desde un archivo JSON."},
       {"type": "IMPROVEMENTS", "text": "Elige qué generaciones entran en juego en cada minijuego."},
       {"type": "IMPROVEMENTS", "text": "Incluye formas regionales, entradas oficiales de la Pokédex en español y nombres de movimientos en español en Learnset Guess."},
       {"type": "IMPROVEMENTS", "text": "En Most Likely To y Pokémon Red Flag / Green Flag, los empates de la votación se resuelven con una segunda vuelta."},
       {"type": "IMPROVEMENTS", "text": "Si el anfitrión pierde la conexión, la sala le espera y conserva la configuración. Quien llega a mitad de ronda la sigue como espectador."},
       {"type": "INTERFACE", "text": "Tema oscuro, con selector para volver al claro."},
       {"type": "INTERFACE", "text": "Logotipo e icono propios y una guía «Cómo jugar» en la pantalla Jugar."},
       {"type": "TECHNICAL", "text": "Los datos de Pokémon y de cartas se guardan en nuestro servidor y se actualizan solos."}
     ]$json$::jsonb,
     CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, '0.2.0', 'Novedades, feedback y saltar minijuego',
     'Página de Novedades, envío de problemas y sugerencias, votación para saltar un minijuego y una gran ronda de arreglos.',
     TIMESTAMP '2026-09-12 17:39:47', true,
     $json$[
       {"type": "NEW", "text": "Nueva página de Novedades: descubre de un vistazo qué ha cambiado en cada versión.", "highlight": true},
       {"type": "NEW", "text": "Reporta un problema o envía una sugerencia desde la web. Si lo haces desde una sala, se adjunta el contexto de la partida.", "highlight": true},
       {"type": "NEW", "text": "Votación para saltar el minijuego en curso: se salta cuando todos los participantes están de acuerdo. Los espectadores pueden seguir la votación.", "highlight": true},
       {"type": "INTERFACE", "text": "Shiny Quiz estrena pantalla: cabecera, barra lateral con la clasificación y cartas de candidato más claras, con tu elección en privado."},
       {"type": "BALANCE", "text": "Los puntos de la sesión dependen de tu posición en cada partida, así que todos los minijuegos pesan igual. Quedar con cero puntos no da premio."},
       {"type": "BALANCE", "text": "Pokémon Team Auction y Pokémon Bluff Auction: 20 segundos por puja por defecto. Si se acaba el tiempo, pasas ese lote. El anfitrión puede quitar el reloj."},
       {"type": "BALANCE", "text": "Quién es Quién — Pokémon: 30 segundos para elegir el secreto. Si se acaba el tiempo, se asigna uno al azar."},
       {"type": "BUGS", "text": "Zoomed Pokémon ya no deja ver la imagen completa antes de tiempo: cada etapa muestra solo su recorte."},
       {"type": "BUGS", "text": "Los plazos de Pokémon Bluff Auction, Pokémon Connections y One of Us Is Fake se respetan siempre."},
       {"type": "BUGS", "text": "Una acción enviada en la ronda anterior ya no se cuela en la nueva, y salir y volver a entrar a una sala funciona bien."},
       {"type": "BUGS", "text": "Importar dilemas de Would You Rather Pokémon ya no deja la lista a medias si algo falla."},
       {"type": "IMPROVEMENTS", "text": "Sketchmon aguanta mejor los dibujos largos, con muchos trazos."},
       {"type": "TECHNICAL", "text": "Revisión técnica completa del servidor y de la web para ganar estabilidad."}
     ]$json$::jsonb,
     CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, '0.3.0', 'Servidor nuevo',
     'Pokémon Universe se muda a un servidor nuevo. Los 28 minijuegos funcionan igual y las salas usan una conexión más ligera.',
     TIMESTAMP '2026-11-03 04:31:18', true,
     $json$[
       {"type": "TECHNICAL", "text": "Todo Pokémon Universe funciona ya sobre un servidor nuevo: salas, perfiles, Novedades, feedback, imágenes y sonidos.", "highlight": true},
       {"type": "IMPROVEMENTS", "text": "Los 28 minijuegos se han trasladado con las mismas reglas, comprobadas partida a partida contra el servidor anterior.", "highlight": true},
       {"type": "TECHNICAL", "text": "Las salas usan una conexión en tiempo real más ligera."},
       {"type": "INTERFACE", "text": "El aviso de conexión de la sala ya no tapa la cabecera y solo dice «Conectando» si tarda más de un instante.", "highlight": true},
       {"type": "TECHNICAL", "text": "Los datos de Pokémon y de cartas del TCG se sincronizan desde el servidor nuevo."},
       {"type": "TECHNICAL", "text": "Pruebas automáticas en un navegador real del acceso, las salas y cada minijuego, en móvil y en escritorio."},
       {"type": "TECHNICAL", "text": "Dependencias actualizadas para cerrar vulnerabilidades."}
     ]$json$::jsonb,
     CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, '0.4.0', 'Minijuegos más justos',
     'Arreglos de bucles, adiós a las copias y revelaciones nuevas en Pokédex Distance, Shiny Quiz, Pokémon Impostor, Higher or Lower, Type Duel y Learnset Guess.',
     TIMESTAMP '2026-11-03 15:09:17', true,
     $json$[
       {"type": "BUGS", "text": "Type Duel ya no puede alargarse sin fin: cada ronda consume un duelo, hay un tope y no se aceptan intentos repetidos. El resultado muestra los tipos.", "highlight": true},
       {"type": "BUGS", "text": "Pokémon Impostor: nueva opción «Saltar» al votar y tope de revotaciones. Si nadie se pone de acuerdo, se sigue sin expulsar a nadie."},
       {"type": "BUGS", "text": "Pokémon Impostor: la fase de pistas siempre tiene plazo y el resultado explica por qué ganó cada bando."},
       {"type": "IMPROVEMENTS", "text": "Pokémon Impostor: el lobby avisa si hay demasiados impostores para los jugadores de la sala."},
       {"type": "BUGS", "text": "Pokédex Distance cuenta bien las rondas superadas y solo acepta formas por defecto."},
       {"type": "BUGS", "text": "Learnset Guess solo cuenta los fallos de quien estaba jugando."},
       {"type": "BUGS", "text": "Higher or Lower, en español y sin botones para quien no juega."},
       {"type": "BUGS", "text": "Los ajustes de cada minijuego usan los mismos límites que el servidor, así que la partida ya no falla al empezar."},
       {"type": "BALANCE", "text": "Adiós a las copias: Higher or Lower oculta las respuestas hasta revelar, Shiny Quiz muestra los votos al revelar y Pokédex Distance oculta las elecciones de los rivales.", "highlight": true},
       {"type": "BALANCE", "text": "Bonus por rapidez en Higher or Lower y por orden de acierto en Learnset Guess, que además avisa cuando quedan 10 segundos."},
       {"type": "BALANCE", "text": "Shiny Quiz: solo salen Pokémon con shiny y las paletas se barajan."},
       {"type": "BALANCE", "text": "Pokédex Distance: como mucho tres desempates. En el tercero cae quien eligió el último, y el resultado lo explica."},
       {"type": "IMPROVEMENTS", "text": "En Pokédex Distance, Shiny Quiz, Pokémon Impostor, Higher or Lower, Type Duel y Learnset Guess, un corte de menos de 8 segundos no te elimina. En Type Duel, si tu rival no vuelve en ese plazo, ganas tú.", "highlight": true},
       {"type": "BUGS", "text": "El buscador de Pokémon y Higher or Lower ya no dan pistas ocultas como el número de la Pokédex, los tipos o las estadísticas."},
       {"type": "NEW", "text": "Animaciones comunes: un cut-in al revelar y puntos que saltan al sumar. Se reducen si tu sistema pide menos movimiento."},
       {"type": "NEW", "text": "Sonidos de interfaz, apagados por defecto y con botón de silencio."},
       {"type": "INTERFACE", "text": "El buscador de Pokémon muestra la carga, los errores y un botón de reintento en los 18 juegos que lo usan."},
       {"type": "INTERFACE", "text": "«Cómo se juega» en el lobby y una intro de 10 segundos con los pasos al empezar, que se puede saltar entre todos, en Pokédex Distance, Shiny Quiz, Pokémon Impostor, Higher or Lower, Type Duel y Learnset Guess."},
       {"type": "INTERFACE", "text": "Revelaciones nuevas: carta que gira con el antes y el después en Shiny Quiz, regla numérica en Pokédex Distance, enfrentamiento VS en Type Duel y barras comparadas con rachas en Higher or Lower."},
       {"type": "INTERFACE", "text": "Pokémon Impostor: al expulsar a alguien, un cut-in a pantalla completa desvela su rol tras una breve pausa."},
       {"type": "INTERFACE", "text": "Learnset Guess: marcador en vivo, pistas que entran animadas y los puntos que hay en juego."},
       {"type": "INTERFACE", "text": "Pokédex Distance: resultados con la distancia de cada ronda, tu mejor acierto y los desempates superados."}
     ]$json$::jsonb,
     CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, '0.5.0', 'Nueva imagen Arcade',
     'Toda la web y los 28 minijuegos se rediseñan, llegan la música y los niveles de cuenta, y el lobby permite elegir varios minijuegos.',
     TIMESTAMP '2026-11-05 12:18:58', true,
     $json$[
       {"type": "INTERFACE", "text": "Nuevo diseño en toda la web: fondo azul noche, tipografías nuevas, cartas y paneles con aire de arcade. Los textos se leen mejor y los botones son fáciles de pulsar en el móvil.", "highlight": true},
       {"type": "INTERFACE", "text": "Los 28 minijuegos estrenan pantalla con el nuevo estilo y aprovechan toda la pantalla en escritorios grandes."},
       {"type": "NEW", "text": "Música chiptune propia en cada fase de la sala, efectos de sonido en los 28 minijuegos y un efecto de victoria al acabar cada partida. Ajusta el volumen de cada canal desde la cabecera.", "highlight": true},
       {"type": "NEW", "text": "Las cuentas registradas ganan experiencia y suben de nivel. Tu nivel aparece sobre tu avatar y la barra de experiencia, en tu perfil.", "highlight": true},
       {"type": "IMPROVEMENTS", "text": "En el lobby eliges uno o varios minijuegos y decides si se juegan en orden, al azar o por votación. Saltar un minijuego pasa al siguiente o termina la sesión."},
       {"type": "INTERFACE", "text": "Cartas de minijuego con ilustración propia, en lugar de emojis, en el lobby, la rotación, la votación y el perfil."},
       {"type": "INTERFACE", "text": "El inicio es ahora una pantalla de título con las novedades, y Jugar se queda en crear sala o unirse con un código."},
       {"type": "INTERFACE", "text": "Cabecera nueva: botón para volver al inicio, código de la sala siempre arriba, ajustes de sonido y acceso rápido para enviar feedback."},
       {"type": "INTERFACE", "text": "Las Novedades se leen como notas de parche: portada de la versión, lo más destacado y línea de tiempo."},
       {"type": "INTERFACE", "text": "Todos los juegos terminan con «Ver clasificación final» y los resultados destacan los récords de la partida."},
       {"type": "MINIGAMES", "text": "Type Chain cambia de reglas: cada cadena tiene un tipo y, por turnos, nombráis Pokémon de ese tipo sin repetir. Gana quien más nombre."},
       {"type": "MINIGAMES", "text": "Pokémon Connections suma 36 categorías nuevas y sus tableros ya no admiten dos soluciones."},
       {"type": "MINIGAMES", "text": "Pokémon Trivia: confirmas tu respuesta antes de enviarla, solo se muestra el dato comparado y ves quién eligió cada opción."},
       {"type": "MINIGAMES", "text": "Pokédex Distance solo muestra las generaciones en juego y lanza confeti cuando clavas el objetivo."},
       {"type": "INTERFACE", "text": "Retoques en Shiny Quiz, Type Duel, Pokémon Bingo y Pokédle Race: votos sobre el sprite, carta ganadora junto al título, sprites que llenan la casilla y tableros de los rivales."},
       {"type": "INTERFACE", "text": "Un único tema: se retiran el tema claro y su selector."},
       {"type": "INTERFACE", "text": "Avatares más sencillos: tu foto o tu inicial. Se retiran los avatares predefinidos y el invitado solo elige un nombre."},
       {"type": "INTERFACE", "text": "Los minijuegos empiezan directamente: se retiran la intro y la guía «Cómo se juega»."},
       {"type": "IMPROVEMENTS", "text": "Más accesible: modo sin animaciones si tu sistema lo pide, avisos para lectores de pantalla y foco ordenado al cambiar de pantalla."},
       {"type": "BUGS", "text": "Los errores de la sala salen una sola vez y en español, los botones ya no tiemblan al pasar el ratón y los sprites que fallan se reintentan."}
     ]$json$::jsonb,
     CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
ON CONFLICT (version) DO NOTHING;
